class CachedProperty:
    def __init__(self, func):
        self.func = func
        self.attr_name = func.__name__

    def __set_name__(self, owner, name):
        self.attr_name = name

    def __get__(self, obj, owner):
        if obj is None:
            return self
        val = self.func(obj)
        obj.__dict__[self.attr_name] = val
        return val

class DataSet:
    def __init__(self, values):
        self.values = values

    @CachedProperty
    def average(self):
        return (
            sum(self.values)
            / len(self.values)
        )

