# Дескриптор с хранением в _data модели
class Field:
    def __init__(
        self, field_type, required=True
    ):
        self.field_type = field_type
        self.required = required

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, owner):
        if obj is None:
            return self
        return obj._data.get(self.name)

    def __set__(self, obj, value):
        if value is None and self.required:
            err = (
                f"Поле {self.name} обязат."
            )
            raise ValueError(err)
        if value is not None and not (
            isinstance(value, self.field_type)
        ):
            err = (
                f"{self.name} не того типа"
            )
            raise TypeError(err)
        obj._data[self.name] = value

class Model:
    def __init__(self, **kwargs):
        self._data = {}
        for k, v in kwargs.items():
            setattr(self, k, v)

class User(Model):
    name = Field(str)
    age = Field(int, required=False)

u = User(name="Alex", age=30)

