def parse_cli_args(argv: list[str]) -> dict:
    cfg = {'host': '127.0.0.1', 'port': 8000}
    i = 0
    while i < len(argv):
        flag = argv[i]
        if flag == '--host' and i + 1 < len(argv):
            cfg['host'] = argv[i + 1]
            i += 2
        elif flag == '--port' and i + 1 < len(argv):
            cfg['port'] = int(argv[i + 1])
            i += 2
        else:
            raise ValueError(f'Unknown or incomplete argument: {flag}')
    return cfg

