class SerializableMixin:
    def __init_subclass__(cls, abstract: bool = False, **kwargs):
        super().__init_subclass__(**kwargs)
        if abstract:
            return
        ver = getattr(cls, 'schema_version', None)
        if not isinstance(ver, int) or isinstance(ver, bool) or ver <= 0:
            raise TypeError(f'{cls.__name__} must define positive int schema_version')
        if not callable(getattr(cls, 'payload', None)):
            raise TypeError(f'{cls.__name__} must define callable payload()')

    def serialize(self) -> dict:
        return {'version': self.schema_version, 'data': self.payload()}

