def _c3_merge(seqs: list[list[str]]) -> list[str]:
    res: list[str] = []
    seqs = [list(s) for s in seqs if s]
    while seqs:
        candidate = None
        for seq in seqs:
            head = seq[0]
            if not any(head in s[1:] for s in seqs):
                candidate = head
                break
        if candidate is None:
            raise TypeError('Inconsistent MRO')
        res.append(candidate)
        seqs = [[x for x in s if x != candidate] for s in seqs]
