        self.item = item

def is_generic_compatible(sub_arg: type, super_arg: type, variance: str) -> bool:
    if variance == 'invariant':
        return sub_arg is super_arg
    if variance == 'covariant':
        return issubclass(sub_arg, super_arg)
    if variance == 'contravariant':
        return issubclass(super_arg, sub_arg)
    raise ValueError(f'Unknown variance: {variance}')

