import inspect

def parse_google_docstring(fn) -> dict:
    doc = inspect.getdoc(fn) or ''
    lines = doc.splitlines()
    summary = lines[0].strip() if lines else ''
    args: dict[str, str] = {}
    returns_lines: list[str] = []
    section = None
    for line in lines[1:]:
        stripped = line.strip()
        if stripped == 'Args:':
            section = 'args'
            continue
        if stripped == 'Returns:':
            section = 'returns'
            continue
        if stripped.endswith(':') and not line.startswith(' '):
            section = 'other'
            continue
        if not stripped:
            continue
        if section == 'args' and ':' in stripped:
            left, desc = stripped.split(':', 1)
            pname = left.split('(', 1)[0].strip()
            args[pname] = desc.strip()
        elif section == 'returns':
            returns_lines.append(stripped)
    sig_params = [p for p in inspect.signature(fn).parameters if p not in ('self', 'cls')]
    missing = sorted(p for p in sig_params if p not in args)
    return {
        'summary': summary,
        'args': args,
        'returns': ' '.join(returns_lines),
        'missing_params': missing,
    }

