from collections import deque

def analyze_gc_graph(roots, graph):
    reachable = set()
    queue = deque(r for r in roots if r in graph)
    while queue:
        node = queue.popleft()
        if node in reachable:
            continue
        reachable.add(node)
        for nxt in graph.get(node, []):
            if nxt not in reachable:
                queue.append(nxt)
    in_deg = {node: 0 for node in graph}
    for src, targets in graph.items():
        for dst in targets:
            if dst in in_deg:
                in_deg[dst] += 1
    unreachable = set(graph.keys()) - reachable
    zero_ref = {n for n in unreachable if in_deg[n] == 0}
    cyclic_garbage = {n for n in unreachable if in_deg[n] > 0}
    return {
        "reachable": reachable,
        "zero_ref": zero_ref,
        "cyclic_garbage": cyclic_garbage,
    }

