class MiniLoop:
    def __init__(self):
        self.ready = deque()
        self.sleeping = []
        self.results = {}

    def create_task(self, name, gen):
        self.ready.append((name, gen))

    def run(self):
        tick = 0
        while self.ready or self.sleeping:
            still_sleeping = []
            for wake_tick, name, gen in self.sleeping:
                if wake_tick <= tick:
                    self.ready.append((name, gen))
                else:
                    still_sleeping.append((wake_tick, name, gen))
            self.sleeping = still_sleeping
            if not self.ready:
                tick += 1
                continue
            batch = len(self.ready)
            for _ in range(batch):
                name, gen = self.ready.popleft()
                try:
                    sig = next(gen)
                except StopIteration as exc:
                    self.results[name] = exc.value
                    continue
                if isinstance(sig, tuple) and len(sig) == 2 and sig[0] == "sleep":
                    self.sleeping.append((tick + max(1, int(sig[1])), name, gen))
                else:
                    self.ready.append((name, gen))
            tick += 1
        return self.results

