import heapq

def estimate_wall_clock(durations, workers):
    if not durations:
        return {"sequential": 0, "unbounded": 0, "pooled": 0}
    seq = sum(durations)
    unbounded = max(durations)
    k = min(max(1, workers), len(durations))
    heap = [0] * k
    heapq.heapify(heap)
    for d in durations:
        earliest = heapq.heappop(heap)
        heapq.heappush(heap, earliest + d)
    return {"sequential": seq, "unbounded": unbounded, "pooled": max(heap)}

