import json
from datetime import datetime
from decimal import Decimal
from uuid import UUID

def _encode_default(obj):
    if isinstance(obj, Decimal):
        return {"__type__": "decimal", "value": str(obj)}
    if isinstance(obj, datetime):
        return {"__type__": "datetime", "value": obj.isoformat()}
    if isinstance(obj, UUID):
        return {"__type__": "uuid", "value": str(obj)}
    if isinstance(obj, set):
        return {"__type__": "set", "value": sorted(obj, key=repr)}
    raise TypeError(f"Тип не сериализуется: {type(obj).__name__}")

def _decode_hook(dct):
    tag = dct.get("__type__")
    if tag == "decimal":
        return Decimal(dct["value"])
    if tag == "datetime":
        return datetime.fromisoformat(dct["value"])
    if tag == "uuid":
        return UUID(dct["value"])
    if tag == "set":
        return set(dct["value"])
    return dct

def dumps_typed(obj):
    return json.dumps(obj, default=_encode_default)

def loads_typed(raw):
    return json.loads(raw, object_hook=_decode_hook)

