import io
import json
import pickle

SAFE_BUILTINS = {"dict", "list", "set", "tuple"}

def safe_json_loads(raw, max_depth=3, max_items=10):
    data = json.loads(raw)
    count = [0]

    def _walk(node, depth):
        if isinstance(node, dict):
            if depth > max_depth:
                raise ValueError("Превышена глубина JSON")
            for k, v in node.items():
                count[0] += 1
                if count[0] > max_items:
                    raise ValueError("Превышен лимит элементов")
                _walk(v, depth + 1)
        elif isinstance(node, list):
            if depth > max_depth:
                raise ValueError("Превышена глубина JSON")
            for item in node:
                count[0] += 1
                if count[0] > max_items:
                    raise ValueError("Превышен лимит элементов")
                _walk(item, depth + 1)

    _walk(data, 1)
    return data

class RestrictedUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if module == "builtins" and name in SAFE_BUILTINS:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(f"Запрещённый символ: {module}.{name}")

