from pathlib import PurePosixPath

def safe_join_posix(base_dir, user_path):
    if not user_path or "\x00" in user_path:
        raise ValueError("Недопустимый путь")
    rel = PurePosixPath(user_path)
    if rel.is_absolute():
        raise ValueError("Абсолютные пути запрещены")
    stack = []
    for part in rel.parts:
        if part in ("", "."):
            continue
        if part == "..":
            if not stack:
                raise ValueError("Обнаружен Path Traversal")
            stack.pop()
        else:
            stack.append(part)
    base = PurePosixPath(base_dir)
    return base.joinpath(*stack)

