def analyze_bytecode(fn):
    total = 0
    globs = set()
    locs = set()
    counts = {}
    for instr in dis.get_instructions(fn):
        total += 1
        counts[instr.opname] = counts.get(instr.opname, 0) + 1
        if instr.opname == "LOAD_GLOBAL" and isinstance(instr.argval, str):
            globs.add(instr.argval)
        elif instr.opname.startswith("LOAD_FAST") and isinstance(instr.argval, str):
            locs.add(instr.argval)
    return {
        "total_ops": total,
        "globals": sorted(globs),
        "locals": sorted(locs),
        "op_counts": counts,
    }

