from pathlib import PurePosixPath

def classify_tree(paths):
    modules = set()
    packages = set()
    all_dirs = set()
    for raw in paths:
        p = PurePosixPath(raw)
        if p.suffix != ".py":
            continue
        parts = p.parts
        for i in range(1, len(parts)):
            all_dirs.add(".".join(parts[:i]))
        if p.name == "__init__.py":
            if len(parts) > 1:
                packages.add(".".join(parts[:-1]))
        else:
            mod_parts = list(parts[:-1]) + [p.stem]
            modules.add(".".join(mod_parts))
    ns_packages = all_dirs - packages
    return {
        "modules": sorted(modules),
        "packages": sorted(packages),
        "namespace_packages": sorted(ns_packages),
    }

