import heapq

def plan_module_load(deps):
    nodes = set(deps.keys())
    for children in deps.values():
        nodes.update(children)
    rev = {n: [] for n in nodes}
    need_count = {n: 0 for n in nodes}
    for mod, imports in deps.items():
        unique_imp = set(imports)
        need_count[mod] = len(unique_imp)
        for imp in unique_imp:
            rev[imp].append(mod)
    heap = [n for n, deg in need_count.items() if deg == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        cur = heapq.heappop(heap)
        order.append(cur)
        for dependent in rev[cur]:
            need_count[dependent] -= 1
            if need_count[dependent] == 0:
                heapq.heappush(heap, dependent)
    if len(order) != len(nodes):
        return {"has_cycle": True, "order": []}
    return {"has_cycle": False, "order": order}

