import re

CLASS_RE = re.compile(r"^\s*class\s+([A-Za-z_][A-Za-z0-9_]*)")
DEF_RE = re.compile(r"^\s*def\s+([A-Za-z_][A-Za-z0-9_]*)")

def lint_pep8(source):
    issues = []
    for idx, line in enumerate(source.splitlines(), 1):
        if len(line) > 79:
            issues.append({"line": idx, "code": "E501"})
        if line.endswith((" ", "\t")):
            issues.append({"line": idx, "code": "W291"})
        if line.strip():
            indent = line[:len(line) - len(line.lstrip(" \t"))]
            if "\t" in indent or len(indent) % 4 != 0:
                issues.append({"line": idx, "code": "E111"})
        m_cls = CLASS_RE.match(line)
        if m_cls:
            cname = m_cls.group(1)
            if not (cname[0].isupper() and "_" not in cname):
                issues.append({"line": idx, "code": "N801"})
        m_def = DEF_RE.match(line)
        if m_def:
            fname = m_def.group(1)
            if fname != fname.lower():
                issues.append({"line": idx, "code": "N802"})
    return sorted(issues, key=lambda item: (item["line"], item["code"]))

