def _parse_ver(v):
    parts = [int(x) for x in v.strip().split(".")]
    while len(parts) < 3:
        parts.append(0)
    return tuple(parts[:3])

def _matches_one(ver, cond):
    cond = cond.strip()
    for op in ("==", "!=", ">=", "<=", "~=", ">", "<", "^"):
        if cond.startswith(op):
            target = _parse_ver(cond[len(op):])
            if op == "==":
                return ver == target
            if op == "!=":
                return ver != target
            if op == ">=":
                return ver >= target
            if op == "<=":
                return ver <= target
            if op == ">":
                return ver > target
            if op == "<":
                return ver < target
            if op == "~=":
                upper = (target[0], target[1] + 1, 0)
                return target <= ver < upper
            if op == "^":
                if target[0] > 0:
                    upper = (target[0] + 1, 0, 0)
                elif target[1] > 0:
                    upper = (0, target[1] + 1, 0)
                else:
                    upper = (0, 0, target[2] + 1)
                return target <= ver < upper
    return ver == _parse_ver(cond)

def select_best_version(available, spec_str):
    conds = [c for c in spec_str.split(",") if c.strip()]
    matched = []
    for raw in available:
        ver = _parse_ver(raw)
        if all(_matches_one(ver, c) for c in conds):
            matched.append((ver, raw))
    if not matched:
        return None
    matched.sort(key=lambda item: item[0])
    return matched[-1][1]

