def check_dependencies(specs, available, lockfile=None):
    candidates = {pkg: set(vers) for pkg, vers in available.items()}
    for pkg, allowed in specs:
        if pkg not in candidates:
            candidates[pkg] = set()
        else:
            candidates[pkg] &= set(allowed)
    conflicts = []
    resolved = {}
    lock_mismatch = []
    for pkg in sorted(candidates):
        valid = candidates[pkg]
        if not valid:
            conflicts.append(pkg)
        else:
            resolved[pkg] = sorted(valid)[-1]
            if lockfile is not None and lockfile.get(pkg) not in valid:
                lock_mismatch.append(pkg)
    return {
        "resolved": resolved,
        "conflicts": conflicts,
        "lock_mismatch": lock_mismatch,
    }

